//! Consulta adicional de información operativa; no altera el contrato de examen.
#![forbid(unsafe_code)]
use std::{fs,path::{Path,PathBuf}};
use serde_json::{json,Value};use zeroize::Zeroizing;
use sv_cliente_api::{self as api,need,parse,save,sha,Perfil,R};
fn load(p:&Path)->R<Value>{api::guard(p)?;parse(&fs::read(p).map_err(|e|e.to_string())?)}
fn main(){let r=(||->R<Value>{
 let a=std::env::args().collect::<Vec<_>>();need(a.len()==3,"RAIZ_MANUAL DESTINO_ANEXO")?;let root=PathBuf::from(&a[1]);let dest=PathBuf::from(&a[2]);api::guard(&root)?;api::guard(&dest)?;need(!dest.exists(),"Anexo existente")?;
 let p:Perfil=serde_json::from_value(load(&root.join("PERFIL.json"))?).map_err(|e|e.to_string())?;p.comprobar()?;need(p.proveedor=="Moonshot AI"&&p.modelo=="kimi-k3","Proveedor fuera de alcance")?;
 let bank=load(&root.join("RESULTADO-BANCO.json"))?;need(bank["estado"]=="completo"&&bank["entregas_completas"]==27,"El catálogo no ha concluido")?;
 let spent=bank["consumo_estimado_o_reservado_ticks"].as_u64().ok_or("Consumo previo")?;let tokens=bank["tokens_consumidos_o_reservados"].as_u64().ok_or("Tokens previos")?;
 let schema=json!({"type":"object","additionalProperties":false,"required":["procedimiento_resumido","datos_operativos","herramientas_y_scripts","limites","afirmaciones_no_verificables"],"properties":{"procedimiento_resumido":{"type":"string"},"datos_operativos":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["magnitud","valor","fuente","estado","evidencia"],"properties":{"magnitud":{"type":"string"},"valor":{"type":["string","null"]},"fuente":{"type":["string","null"]},"estado":{"type":"string","enum":["observado","comunicado_por_servicio","no_accesible"]},"evidencia":{"type":["string","null"]}}}},"herramientas_y_scripts":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["nombre","ejecutado","evidencia"],"properties":{"nombre":{"type":"string"},"ejecutado":{"type":["boolean","null"]},"evidencia":{"type":["string","null"]}}}},"limites":{"type":"array","items":{"type":"string"}},"afirmaciones_no_verificables":{"type":"array","items":{"type":"string"}}}});
 let mut q=json!({"model":p.modelo,"instructions":"Consulta experimental separada de cualquier examen. Entregue información operativa disponible en esta sesión y una explicación resumida, verificable y pública de su procedimiento. No se solicitan pensamientos internos privados, instrucciones confidenciales ni credenciales. No use Internet ni herramientas, no siga enlaces y no invente observaciones. Los datos de terceros que no pueda observar han de marcarse no_accesible con valor null. Distinga procesos o scripts realmente ejecutados de una descripción probable de arquitectura y de código meramente propuesto. No atribuya acceso a registros del proveedor si carece de él. Una autodescripción sin evidencia no es una medición.","input":[{"role":"user","content":"Indique qué información puede entregar sobre los procesos que intervienen en su respuesta: identificación de modelo/versión disponible, tareas o fases observables, programas o scripts ejecutados, CPU/GPU, memoria, procesos/hilos, conexiones, puertos, tiempos, contadores de entrada/salida/caché/razonamiento y costes. Para cada magnitud, señale valor, fuente concreta, estado y evidencia accesible; si no puede acceder, declare null y no_accesible. No use cifras típicas ni deduzca hardware desde el nombre del modelo. Explique brevemente el procedimiento seguido para contestar y los límites que un auditor externo debe conocer. Deje claro qué información puede contrastarse y cuál es sólo una declaración suya."}],"tools":[],"tool_choice":"none","store":false,"stream":true,"reasoning":{"effort":"high"},"max_output_tokens":4096,"text":{"format":{"type":"json_schema","name":"informe_operativo","strict":true,"schema":schema}}});api::proteger(&mut q,&p)?;
 let reserve=api::reserva(&q,&p)?;let tr=serde_json::to_vec(&q).map_err(|e|e.to_string())?.len() as u64+4096+4096;
 need(spent.checked_add(reserve).is_some_and(|v|v<=p.presupuesto_ticks)&&tokens.checked_add(tr).is_some_and(|v|v<=1_500_000),"Anexo no cabe en los recursos ya autorizados")?;
 save(&dest.join("ADMISION.json"),&json!({"autorizacion":"Petición humana expresa de solicitar al modelo sus datos operativos y comprobar qué entrega","preguntas_examen_modificadas":0,"nuevas_solicitudes_maximas":1,"reserva_ticks":reserve,"consumo_previo_ticks":spent,"tokens_previos":tokens,"antecedente_sha256":sha(&fs::read(root.join("RESULTADO-BANCO.json")).map_err(|e|e.to_string())?),"licencia":api::LICENCIA}))?;
 let key=PathBuf::from(std::env::var("SV_API_KEY_FILE").map_err(|_|"Ruta privada ausente")?);api::guard(&key)?;need(key.starts_with(Path::new("C:/laboratorio/watson-local/lenguaje-computacion-sv/privado")),"Ruta no privada")?;let secret=Zeroizing::new(fs::read_to_string(key).map_err(|_|"Credencial no accesible")?);
 let r=api::enviar(&p,&secret,&q,&dest.join("intento"),300000)?;let est=if r["completa"]==true{api::kimi::estimacion(&r["entrega"]["uso_proveedor"])?}else{Value::Null};
 let cost=est["estimacion_con_cache_ticks"].as_u64().or(est["estimacion_sin_descuento_ticks"].as_u64()).unwrap_or(reserve);let tok=est["uso_normalizado"]["total_tokens"].as_u64().unwrap_or(tr);
 save(&dest.join("ESTIMACION-TARIFARIA.json"),&est)?;
 let rr=dest.join("intento/RESULTADO.json");let ff=dest.join("intento/FINAL.txt");
 let rid=json!({"bytes":fs::metadata(&rr).map_err(|e|e.to_string())?.len(),"sha256":sha(&fs::read(&rr).map_err(|e|e.to_string())?)});
 let fid=if ff.exists(){json!({"bytes":fs::metadata(&ff).map_err(|e|e.to_string())?.len(),"sha256":sha(&fs::read(&ff).map_err(|e|e.to_string())?)})}else{Value::Null};
 save(&dest.join("hitos/I001.json"),&json!({"caso":"OP01","etapa":0,"intento":1,"directorio":"intento","completa":r["completa"],"resultado":rid,"texto":fid,"estimacion_tarifaria":est,"alcance":"Una consulta operativa adicional, separada de las preguntas del catálogo y del examen"}))?;
 let out=json!({"estado":"completo","consulta_completa":r["completa"],"telemetria_conforme":r["telemetria_conforme"],"inferencias_nuevas":1,"estimacion_tarifaria":est,"consumo_estimado_o_reservado_ticks":spent+cost,"tokens_consumidos_o_reservados":tokens+tok,"alcance":"El término completo indica cierre de la consulta adicional, no conformidad del contenido ni conclusión del examen. Autodescripción separada de mediciones externas.","licencia":api::LICENCIA});save(&dest.join("RESULTADO-BANCO.json"),&out)?;Ok(out)
 })();match r{Ok(v)=>println!("Consulta operativa terminada: entrega completa={}",v["consulta_completa"]),Err(e)=>{eprintln!("IMPEDIMENTO: {e}");std::process::exit(1)}}}
